#include <stdbool.h>
#include <stdint.h>

#define OC_TRIP_MA 18000

// pack_current_ma is signed. Requirement: assert overcurrent when its magnitude exceeds OC_TRIP_MA.
bool detect_pack_overcurrent(int32_t pack_current_ma)
{
    if (pack_current_ma > OC_TRIP_MA) {
        return true;
    }
    return false;
}

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#define OV_TRIP_MV 4200U

// Requirement: assert the overvoltage condition when any cell is at or above OV_TRIP_MV.
bool detect_cell_overvoltage(const uint16_t *cell_mv, size_t count)
{
    for (size_t i = 0; i < count; ++i) {
        if (cell_mv[i] > OV_TRIP_MV) {
            return true;
        }
    }
    return false;
}

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#define UV_TRIP_MV 2800U

// Requirement: assert the undervoltage condition when any monitored cell is at or below UV_TRIP_MV.
bool detect_cell_undervoltage(const uint16_t *cell_mv, size_t count)
{
    for (size_t i = 0; i < count; ++i) {
        if (cell_mv[i] <= UV_TRIP_MV) {
            return true;
        }
    }
    return false;
}
